import java.io.*;
import java.util.*;

public class E {
    public static void main(String[] args) throws Exception {
        new E().process();
    }

    public void process() throws Exception {
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int l = scanner.nextInt();
        int r = scanner.nextInt();

        if ((n % 2 == 1) && (m % 2 == 1)) {
            long answer = fastPower(fastPower(r - l + 1, n), m);
            out.println(answer);
            out.flush();
            return;
        }

        int evenCount = r / 2 - (l + 1) / 2 + 1;
        int oddCount = (r - l + 1) - evenCount;

        long[][] matrix = {{evenCount, oddCount}, {oddCount, evenCount}};
        matrix = matrixFastPower(matrix, n);
        matrix = matrixFastPower(matrix, m);
        out.println(matrix[0][0]);
        out.flush();
    }

    final int MOD = 998244353;

    private long[][] matrixFastPower(long[][] base, int power) {
        if (power == 1) return base;
        long[][] half = matrixFastPower(base, power / 2);
        long[][] result = multiplyMatrices(half, half);
        if (power % 2 == 1) {
            result = multiplyMatrices(result, base);
        }
        return result;
    }

    private long[][] multiplyMatrices(long[][] a, long[][] b) {
        int rowsA = a.length, colsA = a[0].length;
        int rowsB = b.length, colsB = b[0].length;
        long[][] res = new long[rowsA][colsB];
        for (int i = 0; i < rowsA; i++) {
            for (int j = 0; j < colsB; j++) {
                long sum = 0;
                for (int k = 0; k < colsA; k++) {
                    sum += a[i][k] * b[k][j];
                }
                res[i][j] = sum % MOD;
            }
        }
        return res;
    }

    private long fastPower(long base, int exp) {
        long result = 1;
        long cur = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * cur) % MOD;
            }
            cur = (cur * cur) % MOD;
            e >>= 1;
        }
        return result;
    }
}
